import struct
import zlib
from .errors import IncompleteRecordError, CorruptRecordError

MAGIC = b"KVR1"
FLAG_VALUE = 0x00
FLAG_TOMBSTONE = 0x01

HEADER_SIZE = 15

def encode_record(key: str, value: str | None) -> bytes:
    if not isinstance(key, str ):
        raise TypeError("key must be str")
    key_bytes = key.encode("utf-8")
    key_len = len(key_bytes)
    if key_len == 0 or key_len > 65535:
        raise ValueError("key length must be 1..65535")
    if value is None:
        flags = FLAG_TOMBSTONE
        value_bytes = b""
    else:
        if not isinstance(value, str):
            raise TypeError("value must be str")
        value_bytes = value.encode("utf-8")
        flags = FLAG_VALUE
    value_len = len(value_bytes)
    crc = zlib.crc32(key_bytes + value_bytes) & 0xFFFFFFFF
    header = struct.pack(">4sBHII", MAGIC, flags, key_len, value_len, crc)
    return header + key_bytes + value_bytes

def decode_record(buf: bytes, offset: int = 0) -> tuple[str, str | None, int]:
    available = len(buf) - offset
    if available < HEADER_SIZE:
        raise IncompleteRecordError("incomplete header")
    magic, flags, key_len, value_len, crc = struct.unpack_from(">4sBHII", buf, offset)
    total = HEADER_SIZE + key_len + value_len
    if available < total:
        raise IncompleteRecordError("incomplete payload")
    if magic != MAGIC:
        raise CorruptRecordError("bad magic")
    if flags not in (0, 1):
        raise CorruptRecordError("bad flags")
    if key_len == 0:
        raise CorruptRecordError("key_len == 0")
    if flags == FLAG_TOMBSTONE and value_len != 0:
        raise CorruptRecordError("tombstone with value")
    key_bytes = buf[offset + HEADER_SIZE : offset + HEADER_SIZE + key len]
    value_bytes = buf[offset + HEADER_SIZE + key_len : offset + total]
    actual_crc = zlib.crc32(key_bytes + value_bytes) & 0xFFFFFFFF
    if actual_crc != crc:
        raise CorruptRecordError("crc mismatch")
    try:
        key_str = key bytes.decode("utf-8")
        value_str = value_bytes.decode("utf-8")
    except UnicodeDecodeError:
        raise CorruptRecordError("invalid utf-8")
    value = None if flags == FLAG_TOMBSTONE else value_str
    return key_str, value, total
